import {planStarship,routeInside} from './starship-plan.mjs';
import {createResourceState,advanceResources,resourceBalance} from '../simulation/resource-loop.mjs';
import {createLifeWorld,createIndividual,experience} from '../simulation/life-story.mjs';
const names=['Ada','Ari','Bea','Bo','Cleo','Dev','Eli','Esme','Finn','Gia','Hana','Ivo','Jae','Kit','Lea','Milo','Nia','Omar','Pip','Rue'];
export function createStarshipSimulation(seed=214,saved){
 const plan=planStarship(seed);let state=saved?structuredClone(saved):createResourceState({food:{initialStock:120,stockCapacity:120,replenishRate:.12},water:{initialStock:180,stockCapacity:180,replenishRate:.2}},[]);
 if(!saved){Object.assign(state,{version:2,seed,remainder:0,visits:0,meals:0,lifeStories:createLifeWorld('aurora-'+seed),crew:[]});for(let i=0;i<20;i++){const berth=plan.berths[i],id='crew-'+i;createIndividual(state.lifeStories,{id,type:'human',label:names[i],capabilities:['crew-duty','meals','rest']});state.crew.push({id,name:names[i],berth:i,room:berth.room,position:{x:berth.x,z:berth.z},phase:'resting',activity:'Resting at assigned berth',wait:2+i*1.3,cycle:i%4,visits:0,walked:0,heading:0,path:[],index:0});}}
 // Preserve V1 history/ledger/identity; discard obsolete routes and relocate to assigned berths.
 if(state.version!==2){for(const p of state.crew){const berth=plan.berths[p.berth];p.position={x:berth.x,z:berth.z};p.room=berth.room;p.path=[];p.index=0;p.target=null;p.phase='resting';p.activity='Settling into refitted quarters';p.wait=1+p.berth*.3;}state.version=2;}
 function destination(p){const i=p.berth,stage=p.cycle++%4,berth=plan.berths[i];if(stage===0)return {room:berth.room,x:berth.x,z:berth.z,activity:'Resting at assigned berth',duration:22};const id=stage===1?['bridge','engineering','life-support','workshop','medical'][i%5]:stage===2?'mess':'recreation',r=plan.rooms.find(r=>r.id===id);return {room:id,x:r.x+(stage===1?(Math.floor(i/5)-1.5)*1.8:(i%10-4.5)*.8),z:r.z+(stage===1?-.6:(i<10?-.65:.65)),activity:stage===1?'On duty · '+r.name:stage===2?'Eating a meal':'Off duty · crew commons',duration:stage===1?18:12};}
 function tick(dt){advanceResources(state,dt);for(const p of state.crew){if(p.phase==='walking'){let remaining=dt*1.05;while(remaining>0&&p.index<p.path.length){const q=p.path[p.index],dx=q.x-p.position.x,dz=q.z-p.position.z,d=Math.hypot(dx,dz),step=Math.min(d,remaining);if(d){p.heading=Math.atan2(dx,dz);p.position.x+=dx/d*step;p.position.z+=dz/d*step;p.walked+=step;}remaining-=step;if(d<=step+1e-9)p.index++;else break;}if(p.index===p.path.length){p.room=p.target.room;p.activity=p.target.activity;p.phase='activity';p.wait=p.target.duration;p.visits++;state.visits++;experience(state.lifeStories,p.id,'compartment-visit',state.seconds,{room:p.room,activity:p.activity});if(p.room==='mess'){const food=Math.min(.6,state.stock.food),water=Math.min(.9,state.stock.water);state.stock.food-=food;state.stock.water-=water;state.used.food+=food;state.used.water+=water;state.meals++;}}}else{p.wait-=dt;if(p.wait<=0){p.target=destination(p);p.path=routeInside(plan,p.position,p.room,p.target,p.target.room);p.index=0;p.phase='walking';p.activity='Walking to '+plan.rooms.find(r=>r.id===p.target.room).name;}}}}
 return {plan,get state(){return state;},update(dt){if(!Number.isFinite(dt)||dt<0)throw Error('Invalid timestep');state.remainder+=dt;while(state.remainder+1e-9>=.1){state.remainder=Math.max(0,state.remainder-.1);if(state.remainder<1e-9)state.remainder=0;tick(.1);}},snapshot:()=>structuredClone(state),balance:()=>({food:resourceBalance(state,'food'),water:resourceBalance(state,'water')})};
}
